  "knowledge": "High-Precision Measurement",
  "description": "Indicates that a specific physical or orbital parameter is known with a high degree of confidence.",
  "definition": "A parameter for which the calculated Relative Uncertainty is less than 5%."
}

{
  "id": 8,
  "knowledge": "Relative Uncertainty",
  "description": "Measures the precision of a measurement as a percentage of the measured value.",
  "definition": "For a value $v$ with positive error $e_1$ and negative error $e_2$, the relative uncertainty ($U_{rel}$) is: $U_{rel} = \\frac{(e_1 - e_2) / 2}{v} \\times 100\\%$"
}
